window.MG_LAZY_DATA["data/lazy/resources/hpc-v26-044-45ea9950203b7056.json"]={sha256:"45ea9950203b70566642fc269ebccce2f97506a3ff4586cf73270625cf4deb89",value:{"sources":[{"id":"v26-case-b5af78a03e311b93","url":"https://doi.org/10.1145/42411.42415","title":"Reevaluating Amdahl’s law","titleEn":"Reevaluating Amdahl’s law","publisher":"John Gustafson / ACM","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-8646d75e80f37cf7","url":"https://hpc.llnl.gov/documentation/tutorials/introduction-parallel-computing-tutorial","title":"Introduction to Parallel Computing: performance analysis","titleEn":"Introduction to Parallel Computing: performance analysis","publisher":"Lawrence Livermore National Laboratory","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v26-044","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v26-044","related":[{"id":"hpc-v26-045","referenceUrls":["https://www.spec.org/cpu2017/Docs/runrules.html"],"title":"SPEC 思維：重複量測、變異與效能宣稱","titleEn":"SPEC principles: repeated timing and performance claims","why":"用兩課的可觀察驗收條件比較模型邊界：交付固定時間工作圖、兩定律對照與比例來源；28.9/25.8可重算，α定義與問題擴大假設不可省略；請另一位學徒依交付件重新推導一組；未通過或資料不足必須明記，不以品牌或峰值取代證據。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver fixed-time work diagrams, comparison of the laws, and fraction provenance. Reproduce both values with α and the expanded-problem assumption explicitly defined. Have another learner derive one case from the handover; label failures or missing evidence without substituting brand names or peak rates.","difference":"建立跑次、輸入hash、編譯選項、暖機、開始完成事件及其他負載欄；1.8/2正確，所有六樣本保留、基準一致且沒有冒稱正式SPEC分數。","differenceEn":"Record run identity, input hash, compiler options, warmup, start and completion events, and competing load. Verify 1.8 and 2, retain all six samples, use the same baseline, and make no official SPEC-score claim.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["縮放速度Sscaled=P−α(P−1)，α是平行執行中串行比例，與Amdahl的基準s不可混用；合成P32、α=.1；同P下α=.2作對照；名義式 32-.1*(32-1) = 28.9 scaled speedup；變更式 32-.2*(32-1) = 25.8 scaled speedup。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","三次量測以中位數描述典型時間；同時保留全部樣本和範圍，不只挑最快一次；合成A時間[9,10,30]秒，B[8,9,10]秒；比較各中位數相對固定基準18秒的速度；名義式 18/10 = 1.8 median-based speedup；變更式 18/9 = 2 median-based speedup。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Scaled speedup is P − α(P−1), where α is the serial fraction of the parallel run, distinct from Amdahl’s baseline fraction. Synthetic P = 32 and α = 0.1 versus 0.2. Nominal 32-.1*(32-1) = 28.9 scaled speedup; changed 32-.2*(32-1) = 25.8 scaled speedup. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Use the median of three runs to describe typical time, while retaining every sample and the range. Synthetic A times [9, 10, 30] and B times [8, 9, 10] seconds. Compare median speedups against one fixed 18-second baseline. Nominal 18/10 = 1.8 median-based speedup; changed 18/9 = 2 median-based speedup. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v26-054","referenceUrls":["https://www.mpi-forum.org/docs/mpi-4.1/mpi41-report.pdf"],"title":"MPI 衍生型別：跨距欄位與檔案視圖","titleEn":"MPI derived datatypes: strided columns and file views","why":"用兩課的可觀察驗收條件比較模型邊界：交付固定時間工作圖、兩定律對照與比例來源；28.9/25.8可重算，α定義與問題擴大假設不可省略；請另一位學徒依交付件重新推導一組；未通過或資料不足必須明記，不以品牌或峰值取代證據。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver fixed-time work diagrams, comparison of the laws, and fraction provenance. Reproduce both values with α and the expanded-problem assumption explicitly defined. Have another learner derive one case from the handover; label failures or missing evidence without substituting brand names or peak rates.","difference":"以合成資料重建「MPI 衍生型別：跨距欄位與檔案視圖」，能分離架構事實、模型假設與驗收證據。完成：交付位址清單、payload/extent 對照與重複型別的界線測試。","differenceEn":"Reconstruct MPI derived datatypes: strided columns and file views with synthetic data; distinguish architecture facts, model assumptions and acceptance evidence. Complete: Deliver address lists, payload/extent comparisons and repeated-datatype boundary tests.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["縮放速度Sscaled=P−α(P−1)，α是平行執行中串行比例，與Amdahl的基準s不可混用；合成P32、α=.1；同P下α=.2作對照；名義式 32-.1*(32-1) = 28.9 scaled speedup；變更式 32-.2*(32-1) = 25.8 scaled speedup。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","由最後元素 31 的末端位置反推 extent，避免用 payload 代替跨距。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Scaled speedup is P − α(P−1), where α is the serial fraction of the parallel run, distinct from Amdahl’s baseline fraction. Synthetic P = 32 and α = 0.1 versus 0.2. Nominal 32-.1*(32-1) = 28.9 scaled speedup; changed 32-.2*(32-1) = 25.8 scaled speedup. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Use the end of element 31 to derive extent instead of substituting payload size.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-29bc9b74199f0f85","url":"https://www.spec.org/cpu2017/Docs/runrules.html","title":"SPEC CPU run and reporting rules","titleEn":"SPEC CPU run and reporting rules","publisher":"SPEC","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-245d4116a6090a19","url":"https://www.mpi-forum.org/docs/mpi-4.1/mpi41-report.pdf","title":"MPI 4.1 standard","titleEn":"MPI 4.1 standard","publisher":"MPI Forum","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
